    font-family: 'Rubik';
    src: local('Rubik ExtraBold Italic'), local('Rubik-ExtraBoldItalic'),
        url('data:font/woff2;charset=utf-8;base64,') format('woff2'),
        url('data:font/woff;charset=utf-8;base64,') format('woff'),
        url('Rubik-ExtraBoldItalic.ttf') format('truetype'),
        url('Rubik-ExtraBoldItalic.svg#Rubik-ExtraBoldItalic') format('svg');
    font-weight: bold;
    font-style: italic;
    font-display: swap;
}

